HIDDEN_DIM = 7168
# Public pointer-table layout of ``trtllm_create_ipc_workspace_for_all_reduce_fusion``:
# three world-sized pointer regions (buffer, flags, Lamport payload) followed by
# the local control pointer.  The kernel derives every device address from this
# table; the raw ``workspace_control`` / ``workspace_payload_<rank>`` bindings
# name the same allocations for the binding's ownership contract.
WORKSPACE_PAYLOAD_BASE_FACTOR = 2
WORKSPACE_CONTROL_INDEX_FACTOR = 3
LAYOUT_CODE_SWIZZLED_128X4 = 0

SPECIALIZATION_GENERIC = "generic"
SPECIALIZATION_T1_E8_SERIAL_CLEAR = "t1_e8_serial_clear"
SPECIALIZATION_T64_E12_RESIDENT = "t64_e12_resident"
SPECIALIZATION_T128_E16_OWNER_FORWARD = "t128_e16_owner_forward"
SPECIALIZATION_SM100_WS8_MID = "sm100_ws8_mid"
SPECIALIZATION_SM103_T1 = "sm103_t1"
SPECIALIZATION_SM103_WS8_MID = "sm103_ws8_mid"
SPECIALIZATION_WIDE_MLP = "wide_mlp"
# Reviewed single-CTA T=1 geometry (one 896-thread CTA per token instead of a
# four-CTA cluster); composes as a suffix of the shape specialization exactly as
# ``_cta1`` is a suffix of the schedule symbol, so its physical module never
# shares a route key with the four-CTA program of the same class.
SPECIALIZATION_CTA1 = "cta1"
# Reviewed shape specializations of the union, keyed by (arch, world_size,
# dtype, launch_with_pdl, tokens, active experts) and filled mechanically from
# the exported routes.  Every other configuration runs the generic schedule of
# its (arch, world_size, dtype, launch_with_pdl) tuple.
