# (arch, world_size, dtype, launch_with_pdl) classes whose persistent program
# is the ``wide_mlp`` schedule for every token count: such a class exports no
# ``generic`` program, and every configuration of the class outside the
# reviewed shape specializations runs ``wide_mlp`` (the same rule the source
# selector applies).
_WIDE_MLP_CLASSES: tuple[tuple[str, int, str, bool], ...] = (
    ("sm_100a", 2, "bfloat16", False),
    ("sm_100a", 2, "bfloat16", True),
    ("sm_100a", 2, "float16", False),
    ("sm_100a", 2, "float16", True),
    ("sm_100a", 4, "float16", False),
    ("sm_100a", 4, "float16", True),
    ("sm_103a", 2, "bfloat16", False),
    ("sm_103a", 4, "bfloat16", False),
    ("sm_103a", 4, "float16", False),
    ("sm_103a", 4, "float16", True),
)
# (arch, world_size) pairs with at least one exported route.
_EXPORTED_SCOPES: frozenset[tuple[str, int]] = frozenset(
    (key[0], key[1]) for key in ROUTES
)
_DTYPE_NAME = {torch.float16: "float16", torch.bfloat16: "bfloat16"}


def arch_for_capability(device_capability: Sequence[int]) -> Optional[str]:
    """Return the exact architecture whose programs serve one compute capability."""

    values = tuple(int(value) for value in device_capability)
    if len(values) != 2:
        return None
    return ARCH_BY_CAPABILITY.get((values[0], values[1]))


def exported_arches() -> tuple[str, ...]:
    """Architectures with at least one exported route."""

    return tuple(
        arch for arch in ARCHES if any(scope[0] == arch for scope in _EXPORTED_SCOPES)
    )


def raw_pointer_keys(world_size: int) -> frozenset[str]:
    """Raw device-address bindings of one exported module: the control pointer
    plus one Lamport payload pointer per rank of the collective."""

    return frozenset(
        (
            "workspace_control",
            *(f"workspace_payload_{peer}" for peer in range(int(world_size))),
        )
    )


def select_specialization(
    arch: str,
    world_size: int,
    dtype_name: str,
    launch_with_pdl: bool,
    token_num: int,
    active_experts: int,
) -> str:
    """Return the reviewed specialization name for one launch configuration."""

    reviewed = _REVIEWED_SPECIALIZATIONS.get(
        (
            str(arch),
            int(world_size),
            str(dtype_name),
            bool(launch_with_pdl),
            int(token_num),
            int(active_experts),
        )
    )
    if reviewed is not None:
        return reviewed
    if (
        str(arch),
        int(world_size),
        str(dtype_name),
        bool(launch_with_pdl),
    ) in _WIDE_MLP_CLASSES:
        return SPECIALIZATION_WIDE_MLP
    return SPECIALIZATION_GENERIC


def route_applies(
    *, world_size: int, device_capability: Sequence[int], emit_moe_allreduce: bool
) -> bool:
    """Whether the verified union export owns this Cake MoE all-reduce call.

    The export owns exactly the (architecture, world size) scopes it exported
    routes for; every other configuration keeps FlashInfer's legacy isolated
    source bundle.
    """

    arch = arch_for_capability(device_capability)
    return (
        arch is not None
        and bool(emit_moe_allreduce)
        and (arch, int(world_size)) in _EXPORTED_SCOPES
    )


def route_module_names(
    *,
    arch: str,
    world_size: int,
    dtype_name: str,
    launch_with_pdl: bool,
    token_num: int,
    active_experts: int,
) -> tuple[str, ...]:
    """Return the rank-ordered module names of one exported route."""

    key = (
        str(arch),
        int(world_size),
        str(dtype_name),
        bool(launch_with_pdl),
        select_specialization(
            arch, world_size, dtype_name, launch_with_pdl, token_num, active_experts
        ),
    )
    names = ROUTES.get(key)
    if names is None:
        raise ValueError(f"unsupported Cake MoE all-reduce union route: {key}")
    if len(names) != int(world_size):
        raise RuntimeError(f"route {key} does not carry one module per rank")
    return tuple(names)


def route_module_name(
    *,
    arch: str,
    world_size: int,
    dtype_name: str,
    launch_with_pdl: bool,
    token_num: int,
    active_experts: int,
    world_rank: int,
) -> str:
    names = route_module_names(
        arch=arch,
        world_size=world_size,
        dtype_name=dtype_name,
        launch_with_pdl=launch_with_pdl,
        token_num=token_num,
        active_experts=active_experts,
    )
    if not 0 <= int(world_rank) < len(names):
        raise ValueError(f"world_rank must be in [0, {len(names)}), got {world_rank}")
    return names[int(world_rank)]


def _source_dir() -> Path:
    installed = jit_env.FLASHINFER_CSRC_DIR / SOURCE_PACKAGE
    if installed.is_dir():
        return installed
    checkout = Path(__file__).resolve().parents[2] / "csrc" / SOURCE_PACKAGE
    if checkout.is_dir():
        return checkout
    raise FileNotFoundError(
        "Cake MoE all-reduce union CUDA sources were not found. Checked:\n"
        f"  - {installed}\n  - {checkout}"
    )


def _source_path(relative: str) -> Path:
    parts = Path(relative).parts
    if (
        parts[:2] != ("csrc", SOURCE_PACKAGE)
        or len(parts) != 4
        or parts[2] not in ARCHES
    ):
        raise ValueError(
            f"exported source path is outside the union package: {relative!r}"
        )
    return _source_dir().joinpath(*parts[2:])


@functools.cache
def verified_sources(name: str) -> tuple[Path, ...]:
    """Resolve one module's sources and verify their recorded SHA-256 digests."""

    record = MODULES[name]
    paths = []
    for relative in record["sources"]:
        path = _source_path(relative)
        if not path.is_file() or path.is_symlink():
            raise FileNotFoundError(
                f"Cake MoE all-reduce union source is missing: {path}"
            )
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        expected = record["source_sha256"][relative]
        if digest != expected:
            raise RuntimeError(
                f"Cake MoE all-reduce union source {relative} does not match its "
                f"exported digest (expected {expected}, found {digest})"
            )
        paths.append(path)
    return tuple(paths)


@functools.cache
def spec(name: str) -> JitSpec:
    record = MODULES[name]
    return gen_jit_spec(
        name=record["cache_name"],
        sources=list(verified_sources(name)),
        extra_cuda_cflags=[
            *_NVCC_FLAGS_BY_ARCH[record["arch"]],
            *record["compile_flags"],
        ],
        extra_include_paths=[_source_dir().parent],
    )


@functools.cache
def load(name: str):
    return spec(name).build_and_load()


_WORKSPACE_POINTERS: dict[int, tuple[weakref.ReferenceType, tuple[int, ...]]] = {}


def register_workspace_pointers(
    workspace_tensor: torch.Tensor, pointers: Sequence[int]
) -> None:
    """Retain the host-known pointer table behind an all-reduce workspace tensor."""

    if (
        not isinstance(workspace_tensor, torch.Tensor)
        or workspace_tensor.dtype != torch.int64
    ):
        raise TypeError("workspace_tensor must be an int64 torch.Tensor")
    values = tuple(int(value) for value in pointers)
    if workspace_tensor.numel() != len(values):
        raise ValueError("workspace pointer count does not match the workspace tensor")
    _WORKSPACE_POINTERS[int(workspace_tensor.data_ptr())] = (
        weakref.ref(workspace_tensor),
        values,
    )


def workspace_pointers(
    workspace_ptrs: torch.Tensor, world_size: int
) -> tuple[int, ...]:
    """Return the first ``3 * world_size + 1`` table entries without a device readback.

    Tables created by ``trtllm_create_ipc_workspace_for_all_reduce_fusion`` are
    registered at creation.  Any other table is read back exactly once outside
    CUDA Graph capture and then retained for the lifetime of that tensor.
    """

    needed = WORKSPACE_CONTROL_INDEX_FACTOR * int(world_size) + 1
    if workspace_ptrs.numel() < needed:
        raise ValueError(f"workspace_ptrs must contain at least {needed} pointers")
    address = int(workspace_ptrs.data_ptr())
    entry = _WORKSPACE_POINTERS.get(address)
    if entry is not None:
        owner, values = entry
        alive = owner()
        if (
            alive is not None
            and int(alive.data_ptr()) == address
            and len(values) >= needed
        ):
            return values[:needed]
        del _WORKSPACE_POINTERS[address]
    if (
        workspace_ptrs.device.type == "cuda"
        and torch.cuda.is_current_stream_capturing()
    ):
        raise RuntimeError(
            "the Cake MoE all-reduce union needs the host-known workspace pointers before "
            "CUDA Graph capture; run one eager call first or create the workspace with "
            "trtllm_create_ipc_workspace_for_all_reduce_fusion"
        )
    values = tuple(int(value) for value in workspace_ptrs[:needed].tolist())
    _WORKSPACE_POINTERS[address] = (weakref.ref(workspace_ptrs), values)
    return values


def launch_grid_x(
    token_num: int,
    cooperative: bool,
    sm_count: int,
    persistent_ctas_per_sm: int,
    cluster_ctas: int,
    max_persistent_clusters: int | None = None,
) -> int:
    """Resident-grid builds launch one cooperative cluster per token; every
    other build uses the SM-bounded persistent cluster grid that keeps the
    module's ``persistent_ctas_per_sm`` CTAs resident on every SM, capped at
    ``max_persistent_clusters`` clusters where the module records a cap.

    ``cluster_ctas`` is the module's recorded cluster width (``launch.cluster``):
    four 224-thread CTAs per token for the derived geometry, one 896-thread CTA
    for the reviewed single-CTA T=1 rows.  Every cluster of the persistent grid
    must be co-resident (each cluster publishes all of its tiles before it
    polls the peers' same-index tiles).  ``max_persistent_clusters``
    (``launch.max_persistent_clusters``) is the module's co-resident cluster
    capacity, the driver's ``cuOccupancyMaxActiveClusters`` answer recorded for
    modules whose residency would otherwise need more than that many clusters
    (five CTAs per SM on 148 SMs are 185 clusters against a capacity of 175);
    ``None`` records no cap.  The exporter verified
    ``grid // cluster_ctas <= cuOccupancyMaxActiveClusters`` for every module
    on the architecture it was exported on, so neither recorded value is ever
    raised here."""

    ctas_per_sm = int(persistent_ctas_per_sm)
    if ctas_per_sm < 1:
        raise ValueError("persistent_ctas_per_sm must be a positive integer")
    cluster = int(cluster_ctas)
    if cluster < 1:
        raise ValueError("cluster_ctas must be a positive integer")
    if max_persistent_clusters is not None and int(max_persistent_clusters) < 1:
        raise ValueError("max_persistent_clusters must be a positive integer or None")
    if cooperative:
        if ctas_per_sm != 1:
            raise ValueError("cooperative modules launch one cluster per token")
        if max_persistent_clusters is not None:
            raise ValueError("cooperative modules record no persistent cluster cap")
        grid = int(token_num) * cluster
    else:
        grid = (
            min(int(sm_count) * ctas_per_sm, int(token_num) * cluster) // cluster
        ) * cluster
        if max_persistent_clusters is not None:
            grid = min(grid, int(max_persistent_clusters) * cluster)
    if grid <= 0:
        raise ValueError("the launch requires at least one complete cluster")
    return grid


@functools.cache
def _dummy(device_index: int, dtype: torch.dtype) -> torch.Tensor:
    return torch.empty(1, dtype=dtype, device=torch.device("cuda", device_index))


@functools.cache
def _sm_count(device_index: int) -> int:
    return int(torch.cuda.get_device_properties(device_index).multi_processor_count)


def run_cake_moe_allreduce_union(
    *,
    backend: Literal["cake"] = "cake",
    world_size: int,
    world_rank: int,
    token_num: int,
    hidden_dim: int,
    workspace_ptrs: torch.Tensor,
    launch_with_pdl: bool,
    residual_in: torch.Tensor,
    rms_gamma: torch.Tensor,
    rms_eps: float,
    scale_factor: float,
    moe_reduction_device_num_experts: int,
    moe_reduction_scale_input: torch.Tensor,
    moe_reduction_active_experts_token_input: torch.Tensor,
    moe_reduction_token_input: torch.Tensor,
    moe_allreduce_out: Optional[torch.Tensor],
    residual_out: torch.Tensor,
    norm_out: torch.Tensor,
    weight_bias: Optional[float],
) -> None:
    """Select and launch one exported union module for the caller's validated tensors."""

    if backend != "cake":
        raise ValueError(f"backend must be 'cake', got {backend!r}")
    world_size = int(world_size)
    if world_size not in WORLD_SIZES:
        raise ValueError(
            f"the Cake MoE all-reduce union export covers world sizes {WORLD_SIZES}"
        )
    if int(hidden_dim) != HIDDEN_DIM:
        raise ValueError(
            f"the Cake MoE all-reduce union export requires hidden_dim={HIDDEN_DIM}"
        )
    if moe_allreduce_out is None:
        raise ValueError("the Cake MoE all-reduce union export emits moe_allreduce_out")
    dtype = moe_reduction_active_experts_token_input.dtype
    dtype_name = _DTYPE_NAME.get(dtype)
    if dtype_name is None:
        raise ValueError(
            "the Cake MoE all-reduce union supports float16 and bfloat16 only"
        )
    device_index = moe_reduction_active_experts_token_input.device.index
    if device_index is None:
        device_index = torch.cuda.current_device()
    capability = tuple(torch.cuda.get_device_capability(device_index))
    arch = arch_for_capability(capability)
    if arch is None or (arch, world_size) not in _EXPORTED_SCOPES:
        raise ValueError(
            "the Cake MoE all-reduce union export has no verified programs for "
            f"SM{capability[0]}{capability[1]} at world size {world_size}"
        )
    name = route_module_name(
        arch=arch,
        world_size=world_size,
        dtype_name=dtype_name,
        launch_with_pdl=bool(launch_with_pdl),
        token_num=int(token_num),
        active_experts=int(moe_reduction_device_num_experts),
        world_rank=int(world_rank),
    )
    record = MODULES[name]
    pointers = workspace_pointers(workspace_ptrs, world_size)
    dummy = _dummy(device_index, dtype)
    values: dict[str, object] = {
        "active_expert_tokens": moe_reduction_active_experts_token_input,
        "expert_scales": moe_reduction_scale_input,
        "token_input": moe_reduction_token_input,
        "residual": residual_in,
        "gamma": rms_gamma,
        "moe_allreduce_out": moe_allreduce_out,
        "residual_out": residual_out,
        "norm_out": norm_out,
        "quant_out": dummy,
        "scale_out": dummy,
        "workspace_tensor": workspace_ptrs,
        "workspace_control": pointers[WORKSPACE_CONTROL_INDEX_FACTOR * world_size],
        "world_rank": int(world_rank),
        "tokens": int(token_num),
        "active_experts": int(moe_reduction_device_num_experts),
        "epsilon": float(rms_eps),
        "weight_bias": float(0.0 if weight_bias is None else weight_bias),
        "scale_factor": float(scale_factor),
        "layout_code": LAYOUT_CODE_SWIZZLED_128X4,
        "grid_x": launch_grid_x(
            int(token_num),
            record["launch"]["cooperative"],
            _sm_count(device_index),
            record["launch"]["persistent_ctas_per_sm"],
            record["launch"]["cluster"][0],
            record["launch"]["max_persistent_clusters"],
        ),
        "grid_y": 1,
        "grid_z": 1,
    }
    for peer in range(world_size):
        values[f"workspace_payload_{peer}"] = pointers[
            WORKSPACE_PAYLOAD_BASE_FACTOR * world_size + peer
        ]
    module = load(name)
    getattr(module, record["ffi_entry"])(
        *(values[key] for _kind, key in record["arg_plan"])
    )


